const generateParticles = (count: number, config: { xRange?: [number, number]; yRange?: [number, number]; sizeRange?: [number, number]; durationRange?: [number, number] } = {}, seedOffset: number = 0) => {
  const { xRange = [0, 100], yRange = [0, 100], sizeRange = [1, 3], durationRange = [2, 5] } = config
  return Array.from({ length: count }, (_, i) => {
    const seed = i + seedOffset
    return { id: i, x: xRange[0] + seededRandom(seed * 1) * (xRange[1] - xRange[0]), y: yRange[0] + seededRandom(seed * 2) * (yRange[1] - yRange[0]), size: sizeRange[0] + seededRandom(seed * 3) * (sizeRange[1] - sizeRange[0]), duration: durationRange[0] + seededRandom(seed * 4) * (durationRange[1] - durationRange[0]), delay: seededRandom(seed * 5) * 5, seed: seededRandom(seed * 6) }
  })
}

function LogPoseCursorTrail() {
  const [trails, setTrails] = useState<Array<{ id: number; x: number; y: number }>>([])
  const trailId = useRef(0); const lastPos = useRef({ x: 0, y: 0 })
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => { const dx = e.clientX - lastPos.current.x; const dy = e.clientY - lastPos.current.y; if (Math.sqrt(dx * dx + dy * dy) < 10) return; lastPos.current = { x: e.clientX, y: e.clientY }; setTrails(prev => [...prev.slice(-12), { id: trailId.current++, x: e.clientX, y: e.clientY }]) }
    window.addEventListener('mousemove', handleMouseMove, { passive: true }); return () => window.removeEventListener('mousemove', handleMouseMove)
  }, [])
  return (<div className="fixed inset-0 pointer-events-none z-100"><svg className="w-full h-full"><defs><radialGradient id="oceanTrail"><stop offset="0%" stopColor="#4a9eff" stopOpacity="0.8" /><stop offset="50%" stopColor="#00bfff" stopOpacity="0.4" /><stop offset="100%" stopColor="#0066cc" stopOpacity="0" /></radialGradient></defs>{trails.map((trail, i) => (<motion.circle key={trail.id} cx={trail.x} cy={trail.y} r={3 + (i / trails.length) * 6} fill="url(#oceanTrail)" initial={{ opacity: 0.8 }} animate={{ opacity: 0, scale: 0.3 }} transition={{ duration: 0.6 }} />))}</svg></div>)
}

