function ScrollableSection({ children, color, onAtTop, onAtBottom }: { children: React.ReactNode; color: string; onAtTop: () => void; onAtBottom: () => void }) {
  const scrollRef = useRef<HTMLDivElement>(null); const [canScrollUp, setCanScrollUp] = useState(false); const [canScrollDown, setCanScrollDown] = useState(true)
  useEffect(() => { const el = scrollRef.current; if (el) { const check = () => { setCanScrollUp(el.scrollTop > 5); setCanScrollDown(el.scrollTop + el.clientHeight < el.scrollHeight - 5) }; check(); el.addEventListener('scroll', check, { passive: true }); return () => el.removeEventListener('scroll', check) } }, [])
  const handleWheel = useCallback((e: React.WheelEvent) => { const el = scrollRef.current; if (!el) return; const atTop = el.scrollTop <= 5; const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 5; if (e.deltaY < 0 && atTop) onAtTop(); else if (e.deltaY > 0 && atBottom) onAtBottom(); else e.stopPropagation() }, [onAtTop, onAtBottom])
  return (<div className="relative w-full h-full flex items-center justify-center"><div ref={scrollRef} onWheel={handleWheel} className="overflow-y-auto overflow-x-hidden max-h-[85vh] w-full op-scroll" style={{ scrollbarWidth: 'thin', scrollbarColor: `${color}50 transparent` }}><style>{`.op-scroll::-webkit-scrollbar{width:8px}.op-scroll::-webkit-scrollbar-track{background:rgba(0,0,0,0.3)}.op-scroll::-webkit-scrollbar-thumb{background:linear-gradient(180deg,${color}90,${color}50);border-radius:4px}`}</style>{children}</div>
    <AnimatePresence>{canScrollUp && (<motion.div className="absolute top-0 left-0 right-0 h-14 pointer-events-none z-20" style={{ background: 'linear-gradient(to bottom, rgba(0,20,40,0.9), transparent)' }} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}><motion.div className="absolute top-3 left-1/2 -translate-x-1/2" animate={{ y: [0, -5, 0] }} transition={{ duration: 1.5, repeat: Infinity }}><span className="text-xl">⚓</span></motion.div></motion.div>)}</AnimatePresence>
    <AnimatePresence>{canScrollDown && (<motion.div className="absolute bottom-0 left-0 right-0 h-20 pointer-events-none z-20" style={{ background: 'linear-gradient(to top, rgba(0,20,40,0.9), transparent)' }} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}><motion.div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex flex-col items-center" animate={{ y: [0, 5, 0] }} transition={{ duration: 1.5, repeat: Infinity }}><span className="text-xs mb-1 tracking-widest" style={{ color: `${color}aa` }}>SAIL ON</span><span className="text-xl">🏴‍☠️</span></motion.div></motion.div>)}</AnimatePresence></div>)
}

export default function OnePiecePortfolio() {
  const [currentSection, setCurrentSection] = useState(0); const [isTransitioning, setIsTransitioning] = useState(false); const [transitionProgress, setTransitionProgress] = useState(0); const [direction, setDirection] = useState<'forward' | 'backward'>('forward'); const [heroStage, setHeroStage] = useState(0); const [lettersRevealed, setLettersRevealed] = useState(0); const containerRef = useRef<HTMLDivElement>(null); const lastScrollTime = useRef(0); const touchStartY = useRef(0); const fullName = "CODE D. PRUDHVI"
  useEffect(() => { const timers = [setTimeout(() => setHeroStage(1), 500), setTimeout(() => setHeroStage(2), 1500), setTimeout(() => setHeroStage(3), 2500), setTimeout(() => setHeroStage(4), 3500), setTimeout(() => setHeroStage(5), 7000), setTimeout(() => setHeroStage(6), 8500)]; return () => timers.forEach(clearTimeout) }, [])
  useEffect(() => { if (heroStage >= 4 && lettersRevealed < fullName.length) { const timer = setTimeout(() => setLettersRevealed(p => p + 1), 80); return () => clearTimeout(timer) } }, [heroStage, lettersRevealed, fullName.length])
  const transitionToSection = useCallback((newIndex: number) => { if (newIndex < 0 || newIndex >= sections.length || isTransitioning) return; setDirection(newIndex > currentSection ? 'forward' : 'backward'); setIsTransitioning(true); setTransitionProgress(0); const duration = 1500; const startTime = Date.now(); const animate = () => { const elapsed = Date.now() - startTime; const progress = Math.min(elapsed / duration, 1); setTransitionProgress(1 - Math.pow(1 - progress, 3)); if (progress < 1) requestAnimationFrame(animate); else { setCurrentSection(newIndex); setIsTransitioning(false); setTransitionProgress(0) } }; requestAnimationFrame(animate) }, [currentSection, isTransitioning])
  const handleWheel = useCallback((e: WheelEvent) => { const now = Date.now(); if (now - lastScrollTime.current < 1800 || isTransitioning) return; const target = e.target as HTMLElement; if (target.closest('.op-scroll')) return; e.preventDefault(); if (e.deltaY > 30 && currentSection < sections.length - 1) { lastScrollTime.current = now; transitionToSection(currentSection + 1) } else if (e.deltaY < -30 && currentSection > 0) { lastScrollTime.current = now; transitionToSection(currentSection - 1) } }, [currentSection, isTransitioning, transitionToSection])
  const goToPrevSection = useCallback(() => { const now = Date.now(); if (now - lastScrollTime.current < 1000 || isTransitioning || currentSection <= 0) return; lastScrollTime.current = now; transitionToSection(currentSection - 1) }, [currentSection, isTransitioning, transitionToSection])
  const goToNextSection = useCallback(() => { const now = Date.now(); if (now - lastScrollTime.current < 1000 || isTransitioning || currentSection >= sections.length - 1) return; lastScrollTime.current = now; transitionToSection(currentSection + 1) }, [currentSection, isTransitioning, transitionToSection])
  const handleTouchStart = (e: React.TouchEvent) => { touchStartY.current = e.touches[0].clientY }; const handleTouchEnd = (e: React.TouchEvent) => { const diff = touchStartY.current - e.changedTouches[0].clientY; if (Math.abs(diff) > 50) { if (diff > 0) goToNextSection(); else goToPrevSection() } }
  useEffect(() => { const handleKeyDown = (e: KeyboardEvent) => { if (e.key === 'ArrowDown' || e.key === ' ') { e.preventDefault(); goToNextSection() } else if (e.key === 'ArrowUp') { e.preventDefault(); goToPrevSection() } }; window.addEventListener('keydown', handleKeyDown); return () => window.removeEventListener('keydown', handleKeyDown) }, [goToNextSection, goToPrevSection])
  useEffect(() => { const container = containerRef.current; if (container) { container.addEventListener('wheel', handleWheel, { passive: false }); return () => container.removeEventListener('wheel', handleWheel) } }, [handleWheel])
  const current = sections[currentSection]; const next = sections[currentSection + 1]; const prev = sections[currentSection - 1]
  const backgrounds: Record<string, string> = { hero: 'radial-gradient(ellipse at 50% 120%, #001a33 0%, #000d1a 40%, #000 70%)', about: 'radial-gradient(ellipse at 50% 50%, #1a0a00 0%, #0d0500 40%, #000 80%)', skills: 'radial-gradient(ellipse at 50% 100%, #1a0033 0%, #0d001a 40%, #000 80%)', experience: 'radial-gradient(ellipse at 50% 50%, #1a1500 0%, #0d0a00 40%, #000 80%)', projects: 'radial-gradient(ellipse at 50% 0%, #1a1a00 0%, #0d0d00 40%, #000 80%)', education: 'radial-gradient(ellipse at 50% 50%, #001a2e 0%, #000d17 40%, #000 80%)', contact: 'radial-gradient(ellipse at 50% 50%, #0a1a2a 0%, #050d15 40%, #000 80%)' }

  return (
    <div ref={containerRef} className="fixed inset-0 overflow-hidden bg-black" onTouchStart={handleTouchStart} onTouchEnd={handleTouchEnd} style={{ perspective: '1500px', perspectiveOrigin: '50% 50%' }}>
      <style dangerouslySetInnerHTML={{ __html: pirateCursorCSS }} />
      <LogPoseCursorTrail />
      <motion.div className="absolute inset-0" animate={{ background: backgrounds[current.id] }} transition={{ duration: 1.2 }} />
      <OceanWaves active={current.id === 'hero' || current.id === 'contact'} />
      <BubbleParticles active={current.id === 'about' || current.id === 'education'} />
      <TreasureSparkles active={current.id === 'projects' || current.id === 'experience'} />
      <DevilFruitAura active={current.id === 'skills'} />
      <StrawHatSilhouette />

      <div className="absolute inset-0" style={{ transformStyle: 'preserve-3d', transform: `translateZ(${isTransitioning ? (direction === 'forward' ? transitionProgress * 1000 : -transitionProgress * 1000) : 0}px)` }}>
        {prev && direction === 'backward' && isTransitioning && (<motion.div className="absolute inset-0" style={{ transform: 'translateZ(1000px) scale(2.5)', opacity: transitionProgress, pointerEvents: 'none', background: backgrounds[prev.id] }} />)}
        <div className="absolute inset-0" style={{ transform: isTransitioning ? direction === 'forward' ? `translateZ(${transitionProgress * 1000}px) scale(${1 + transitionProgress * 0.6})` : `translateZ(${-transitionProgress * 1000}px) scale(${1 - transitionProgress * 0.4})` : 'translateZ(0) scale(1)', opacity: isTransitioning ? 1 - transitionProgress * 0.6 : 1 }}>
          <div className="absolute inset-0 flex items-center justify-center z-20">
            {current.id === 'hero' && <HeroContent stage={heroStage} lettersRevealed={lettersRevealed} fullName={fullName} />}
            {current.id === 'about' && <AboutContent onAtTop={goToPrevSection} onAtBottom={goToNextSection} />}
            {current.id === 'skills' && <SkillsContent onAtTop={goToPrevSection} onAtBottom={goToNextSection} />}
            {current.id === 'experience' && <ExperienceContent onAtTop={goToPrevSection} onAtBottom={goToNextSection} />}
            {current.id === 'projects' && <ProjectsContent onAtTop={goToPrevSection} onAtBottom={goToNextSection} />}
            {current.id === 'education' && <EducationContent onAtTop={goToPrevSection} onAtBottom={goToNextSection} />}
            {current.id === 'contact' && <ContactContent onAtTop={goToPrevSection} onAtBottom={goToNextSection} />}
          </div>
        </div>
        {next && direction === 'forward' && (<motion.div className="absolute inset-0" style={{ transform: `translateZ(${-1500 + (isTransitioning ? transitionProgress * 1500 : 0)}px) scale(${0.2 + (isTransitioning ? transitionProgress * 0.8 : 0)})`, opacity: isTransitioning ? 0.2 + transitionProgress * 0.8 : 0.2, pointerEvents: 'none', background: backgrounds[next.id] }}><div className="absolute inset-0 flex items-center justify-center"><div className="text-center"><motion.span className="text-5xl block mb-3" animate={{ scale: [1, 1.2, 1], rotate: [0, 10, -10, 0] }} transition={{ duration: 2, repeat: Infinity }}>🏴‍☠️</motion.span><p className="text-sm tracking-widest mb-1" style={{ color: next.color }}>{next.crew}</p><p className="text-2xl font-bold" style={{ color: next.accent }}>{next.name.toUpperCase()}</p></div></div></motion.div>)}
      </div>

      <div className="absolute inset-0 pointer-events-none" style={{ transformStyle: 'preserve-3d' }}>{[...Array(10)].map((_, i) => (<motion.div key={`ring-${i}`} className="absolute left-1/2 top-1/2 rounded-full" style={{ width: `${100 + i * 100}%`, height: `${100 + i * 100}%`, border: `2px solid ${current.color}${Math.max(5, 20 - i * 2).toString(16).padStart(2, '0')}`, transform: `translate(-50%, -50%) translateZ(${-i * 200}px)` }} animate={{ rotateZ: i % 2 === 0 ? [0, 360] : [360, 0] }} transition={{ duration: 80 + i * 10, repeat: Infinity, ease: 'linear' }} />))}</div>
      <div className="absolute inset-0 pointer-events-none z-30" style={{ background: 'radial-gradient(ellipse at 50% 50%, transparent 30%, rgba(0,10,20,0.8) 100%)' }} />

      <div className="fixed right-6 top-1/2 -translate-y-1/2 z-50 flex flex-col gap-3">{sections.map((section, i) => (<motion.button key={section.id} onClick={() => !isTransitioning && transitionToSection(i)} className="group flex items-center gap-3" disabled={isTransitioning} whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }}><span className="text-xs tracking-wider opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-2 group-hover:translate-x-0" style={{ color: currentSection === i ? section.color : 'rgba(255,255,255,0.4)' }}>{section.name}</span><motion.div className="relative w-4 h-4 rounded-full" style={{ background: currentSection === i ? `radial-gradient(circle, ${section.color}, ${section.color}80)` : 'transparent', border: `2px solid ${currentSection === i ? section.color : 'rgba(255,255,255,0.3)'}`, boxShadow: currentSection === i ? `0 0 15px ${section.color}` : 'none' }} animate={currentSection === i ? { scale: [1, 1.3, 1] } : {}} transition={{ duration: 1.5, repeat: Infinity }} /></motion.button>))}</div>

      <motion.div className="fixed top-6 right-6 text-right z-50" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} key={current.crew}><div className="flex items-center gap-3 justify-end"><motion.span className="text-3xl" animate={{ scale: [1, 1.15, 1], rotate: [0, 10, -10, 0] }} transition={{ duration: 3, repeat: Infinity }}>🏴‍☠️</motion.span><div><motion.p className="text-sm font-bold tracking-widest" style={{ color: current.color }}>{current.crew} PIRATES</motion.p><motion.p className="text-xs text-white/50 italic">{current.motto}</motion.p></div></div></motion.div>
      <div className="fixed bottom-6 left-6 z-50"><p className="text-xs text-white/30 tracking-wider"><motion.span style={{ color: current.color }} animate={{ opacity: [0.5, 1, 0.5] }} transition={{ duration: 2, repeat: Infinity }}>{String(currentSection + 1).padStart(2, '0')}</motion.span><span className="mx-2">⚓</span><span>{String(sections.length).padStart(2, '0')}</span></p></div>

      <AnimatePresence>{currentSection === 0 && heroStage >= 6 && !isTransitioning && (<motion.div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-50 text-center" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }}><motion.p className="text-sm tracking-[0.3em] text-blue-400/60 mb-4" animate={{ opacity: [0.4, 1, 0.4] }} transition={{ duration: 2, repeat: Infinity }}>SET SAIL FOR ADVENTURE</motion.p><motion.div className="text-3xl" animate={{ y: [0, -10, 0], rotate: [0, 10, -10, 0] }} transition={{ duration: 2, repeat: Infinity }}>🚢</motion.div></motion.div>)}</AnimatePresence>
      <AnimatePresence>{isTransitioning && (<motion.div className="absolute inset-0 z-40 pointer-events-none" initial={{ opacity: 0 }} animate={{ opacity: [0, 0.3, 0] }} transition={{ duration: 0.8 }} style={{ background: direction === 'forward' ? `radial-gradient(ellipse at 50% 50%, ${next?.color || '#fff'}60, transparent 70%)` : `radial-gradient(ellipse at 50% 50%, ${prev?.color || '#fff'}60, transparent 70%)` }} />)}</AnimatePresence>
    </div>
  )
}

function HeroContent({ stage, lettersRevealed, fullName }: { stage: number; lettersRevealed: number; fullName: string }) {
  return (<div className="text-center px-6 relative"><motion.div className="mb-6 relative" initial={{ opacity: 0, scale: 0, y: -50 }} animate={{ opacity: stage >= 2 ? 1 : 0, scale: stage >= 2 ? 1 : 0, y: stage >= 2 ? 0 : -50 }} transition={{ duration: 1.5, type: 'spring' }}><motion.span className="text-8xl md:text-9xl block" style={{ filter: 'drop-shadow(0 0 30px rgba(255,215,0,0.5))' }} animate={{ rotate: [0, 5, -5, 0], scale: [1, 1.05, 1] }} transition={{ duration: 4, repeat: Infinity }}>🎩</motion.span><motion.div className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-32 h-1 rounded-full" style={{ background: 'linear-gradient(90deg, transparent, #ff4444, #ffd700, #ff4444, transparent)' }} animate={{ scaleX: [0.5, 1, 0.5], opacity: [0.5, 1, 0.5] }} transition={{ duration: 2, repeat: Infinity }} /></motion.div><motion.p className="text-sm md:text-base tracking-[0.5em] text-red-400/60 mb-8" initial={{ opacity: 0, y: -20 }} animate={{ opacity: stage >= 3 ? 1 : 0, y: stage >= 3 ? 0 : -20 }} transition={{ duration: 1 }}>WANTED - DEAD OR ALIVE</motion.p><h1 className="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-bold tracking-wider" style={{ textShadow: '0 0 30px #ff4444, 0 0 60px #ffd700' }}>{fullName.split('').map((letter, i) => (<motion.span key={i} className="inline-block" initial={{ opacity: 0, y: 50, scale: 0.5, rotateX: -90 }} animate={{ opacity: i < lettersRevealed ? 1 : 0, y: i < lettersRevealed ? 0 : 50, scale: i < lettersRevealed ? 1 : 0.5, rotateX: i < lettersRevealed ? 0 : -90, color: i < lettersRevealed ? '#ffd700' : 'transparent' }} transition={{ duration: 0.5, ease: [0.34, 1.56, 0.64, 1] }}>{letter === ' ' ? '\u00A0' : letter}</motion.span>))}</h1><motion.div className="mt-6 flex items-center justify-center gap-4" initial={{ opacity: 0 }} animate={{ opacity: stage >= 5 ? 1 : 0 }} transition={{ duration: 1 }}><motion.span className="text-2xl" animate={{ rotate: [0, 360] }} transition={{ duration: 10, repeat: Infinity, ease: 'linear' }}>☠️</motion.span><motion.p className="text-2xl md:text-3xl font-bold" style={{ color: '#ff4444', textShadow: '0 0 20px #ff4444' }}>BOUNTY: {portfolioData.bounty}</motion.p><motion.span className="text-2xl" animate={{ rotate: [0, -360] }} transition={{ duration: 10, repeat: Infinity, ease: 'linear' }}>☠️</motion.span></motion.div><motion.p className="text-xl md:text-2xl tracking-[0.4em] mt-6 text-white" style={{ textShadow: '0 0 15px rgba(74,158,255,0.5)' }} initial={{ opacity: 0, y: 20 }} animate={{ opacity: stage >= 6 ? 1 : 0, y: stage >= 6 ? 0 : 20 }} transition={{ duration: 1 }}>SOFTWARE PIRATE</motion.p><motion.p className="text-lg text-blue-400/70 mt-6 italic" initial={{ opacity: 0 }} animate={{ opacity: stage >= 6 ? [0.6, 1, 0.6] : 0 }} transition={{ duration: 2, repeat: Infinity }}>I Will Be King of the Pirates!</motion.p></div>)
}

function AboutContent({ onAtTop, onAtBottom }: { onAtTop: () => void; onAtBottom: () => void }) {
  return (<ScrollableSection color="#ff6600" onAtTop={onAtTop} onAtBottom={onAtBottom}><div className="max-w-4xl mx-auto px-6 py-8"><motion.div className="text-center mb-8" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}><motion.span className="text-6xl block mb-4" animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ duration: 3, repeat: Infinity }}>🍖</motion.span><motion.h2 className="text-4xl sm:text-5xl md:text-6xl font-bold" style={{ color: '#ffaa00', textShadow: '0 0 40px rgba(255,170,0,0.6)' }}>THE CAPTAIN</motion.h2><motion.p className="text-orange-300/70 italic mt-2">A man dies when he is forgotten</motion.p></motion.div><motion.div className="relative p-8 rounded-2xl border-4 border-double" style={{ background: 'linear-gradient(135deg, rgba(50,25,0,0.9) 0%, rgba(30,15,0,0.95) 100%)', borderColor: '#8B4513' }} initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1, delay: 0.3 }}><motion.div className="absolute -top-6 left-1/2 -translate-x-1/2 px-6 py-2 rounded-full" style={{ background: 'linear-gradient(90deg, #8B4513, #d4a056, #8B4513)', border: '2px solid #ffd700' }}><span className="text-white font-bold tracking-widest">WANTED POSTER</span></motion.div><motion.p className="text-lg md:text-xl text-orange-100/90 leading-relaxed mt-4" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.6 }}>{portfolioData.about}</motion.p><div className="mt-8 grid grid-cols-2 md:grid-cols-4 gap-4">{portfolioData.stats.map((stat, index) => (<motion.div key={stat.label} className="text-center p-4 rounded-xl" style={{ background: 'linear-gradient(135deg, rgba(139,69,19,0.4) 0%, rgba(70,35,10,0.6) 100%)', border: '2px solid rgba(212,160,86,0.4)' }} initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.8 + index * 0.15 }} whileHover={{ scale: 1.08, borderColor: '#ffd700' }}><motion.span className="text-2xl block mb-2" animate={{ y: [0, -5, 0] }} transition={{ duration: 2, repeat: Infinity, delay: index * 0.2 }}>{stat.icon}</motion.span><p className="text-3xl font-bold text-orange-400">{stat.value}</p><p className="text-sm text-orange-200/60 mt-1">{stat.label}</p></motion.div>))}</div></motion.div></div></ScrollableSection>)
}

function SkillsContent({ onAtTop, onAtBottom }: { onAtTop: () => void; onAtBottom: () => void }) {
  const [activeCategory, setActiveCategory] = useState<string | null>(null)
  return (<ScrollableSection color="#9400d3" onAtTop={onAtTop} onAtBottom={onAtBottom}><div className="max-w-6xl mx-auto px-4 py-8"><motion.div className="text-center mb-6" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}><motion.span className="text-5xl block mb-3" animate={{ scale: [1, 1.2, 1], rotate: [0, 360] }} transition={{ duration: 4, repeat: Infinity }}>🍇</motion.span><motion.h2 className="text-4xl sm:text-5xl md:text-6xl font-bold" style={{ color: '#ff69b4', textShadow: '0 0 30px rgba(255,105,180,0.5)' }}>DEVIL FRUITS</motion.h2><motion.p className="text-purple-300/70 italic mt-2">Power of the Sea Devil</motion.p></motion.div><div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">{Object.entries(skillsData).map(([category, data], catIndex) => (<motion.div key={category} className="relative p-4 rounded-xl border-2 overflow-hidden group" style={{ background: `linear-gradient(135deg, ${data.color}20, ${data.color}05)`, borderColor: activeCategory === category ? data.color : `${data.color}40` }} initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: catIndex * 0.1 }} onHoverStart={() => setActiveCategory(category)} onHoverEnd={() => setActiveCategory(null)} whileHover={{ scale: 1.02, boxShadow: `0 10px 40px ${data.color}40` }}><motion.div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity" style={{ background: `radial-gradient(ellipse at 50% 0%, ${data.color}30, transparent 70%)` }} /><div className="flex items-center gap-3 mb-4 pb-3 border-b" style={{ borderColor: `${data.color}40` }}><motion.span className="text-2xl" animate={activeCategory === category ? { rotate: [0, 360], scale: [1, 1.3, 1] } : {}} transition={{ duration: 0.8 }}>{data.icon}</motion.span><div><h3 className="text-sm font-bold tracking-wider" style={{ color: data.color }}>{category.toUpperCase()}</h3><p className="text-xs text-white/40 italic">{data.fruit} • {data.power}</p></div></div><div className="flex flex-wrap gap-2">{data.skills.map((skill, i) => (<motion.span key={skill} className="px-3 py-1.5 text-sm rounded-full" style={{ background: `${data.color}25`, border: `1px solid ${data.color}50`, color: `${data.color}ee` }} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: catIndex * 0.1 + i * 0.03 }} whileHover={{ scale: 1.15, boxShadow: `0 0 15px ${data.color}`, color: '#fff' }}>{skill}</motion.span>))}</div></motion.div>))}</div><motion.div className="text-center mt-6" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 1 }}><p className="text-purple-400/60"><motion.span className="text-2xl font-bold text-purple-400" animate={{ scale: [1, 1.1, 1] }} transition={{ duration: 2, repeat: Infinity }}>{Object.values(skillsData).reduce((acc, cat) => acc + cat.skills.length, 0)}</motion.span> Devil Fruit powers awakened</p></motion.div></div></ScrollableSection>)
}

function ExperienceContent({ onAtTop, onAtBottom }: { onAtTop: () => void; onAtBottom: () => void }) {
  const [activeExp, setActiveExp] = useState<number | null>(null)
  return (<ScrollableSection color="#ffd700" onAtTop={onAtTop} onAtBottom={onAtBottom}><div className="max-w-4xl mx-auto px-6 py-8"><motion.div className="text-center mb-8" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}><motion.span className="text-6xl block mb-3" animate={{ scale: [1, 1.1, 1], x: [-5, 5, -5] }} transition={{ duration: 3, repeat: Infinity }}>🚢</motion.span><motion.h2 className="text-4xl sm:text-5xl md:text-6xl font-bold" style={{ color: '#ffd700', textShadow: '0 0 40px rgba(255,215,0,0.6)' }}>VOYAGE LOG</motion.h2><motion.p className="text-yellow-300/70 italic mt-2">The sea is vast</motion.p></motion.div><div className="relative"><motion.div className="absolute left-0 md:left-6 top-0 bottom-0 w-1 rounded-full" style={{ background: 'linear-gradient(to bottom, #4a9eff, #ffd700, #4a9eff)' }} initial={{ height: 0 }} animate={{ height: '100%' }} transition={{ duration: 1.5, delay: 0.5 }} /><div className="space-y-8 pl-8 md:pl-16">{portfolioData.experience.map((exp, index) => (<motion.div key={`${exp.company}-${exp.role}`} className="relative" initial={{ opacity: 0, x: -50 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.8, delay: 0.5 + index * 0.3 }} onHoverStart={() => setActiveExp(index)} onHoverEnd={() => setActiveExp(null)}><motion.div className="absolute -left-8 md:-left-10 top-6 w-8 h-8 rounded-full border-4 border-blue-400 bg-black flex items-center justify-center" style={{ boxShadow: '0 0 20px rgba(74,158,255,0.6)' }} animate={activeExp === index ? { scale: [1, 1.2, 1], boxShadow: ['0 0 20px rgba(74,158,255,0.6)', '0 0 40px rgba(255,215,0,0.9)', '0 0 20px rgba(74,158,255,0.6)'] } : {}} transition={{ duration: 1, repeat: activeExp === index ? Infinity : 0 }}><span className="text-lg">{exp.icon}</span></motion.div><motion.div className="p-6 rounded-2xl border-2" style={{ background: 'linear-gradient(135deg, rgba(0,26,51,0.9) 0%, rgba(0,13,26,0.95) 100%)', borderColor: activeExp === index ? '#ffd700' : 'rgba(74,158,255,0.4)' }} whileHover={{ scale: 1.02 }}><div className="flex items-center gap-2 mb-2"><span className="px-3 py-1 rounded-full text-xs font-bold" style={{ background: 'linear-gradient(90deg, #4a9eff, #ffd700)', color: '#000' }}>{exp.crew}</span></div><div className="flex flex-col md:flex-row md:items-center md:justify-between mb-4"><div><h3 className="text-xl font-bold text-yellow-400">{exp.role}</h3><p className="text-blue-200/80">{exp.company}</p></div><div className="text-right mt-2 md:mt-0"><p className="text-yellow-300/80 text-sm">{exp.period}</p><p className="text-blue-200/50 text-xs">{exp.location}</p></div></div><ul className="space-y-3">{exp.highlights.map((highlight, i) => (<motion.li key={i} className="flex items-start gap-3 text-blue-100/80 text-sm" initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.5, delay: 0.6 + i * 0.1 }}><motion.span className="text-yellow-500 mt-0.5 shrink-0" animate={activeExp === index ? { rotate: [0, 360] } : {}} transition={{ duration: 0.8, delay: i * 0.1 }}>⚓</motion.span><span>{highlight}</span></motion.li>))}</ul></motion.div></motion.div>))}</div></div></div></ScrollableSection>)
}

function ProjectsContent({ onAtTop, onAtBottom }: { onAtTop: () => void; onAtBottom: () => void }) {
  const [hoveredProject, setHoveredProject] = useState<string | null>(null)
  return (<ScrollableSection color="#ffd700" onAtTop={onAtTop} onAtBottom={onAtBottom}><div className="max-w-6xl mx-auto px-6 py-8"><motion.div className="text-center mb-8" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}><motion.span className="text-5xl block mb-3" animate={{ scale: [1, 1.2, 1], rotate: [0, 10, -10, 0] }} transition={{ duration: 2, repeat: Infinity }}>💎</motion.span><motion.h2 className="text-4xl sm:text-5xl md:text-6xl font-bold" style={{ color: '#ffd700', textShadow: '0 0 30px rgba(255,215,0,0.5)' }}>TREASURE CHEST</motion.h2><motion.p className="text-yellow-300/70 italic mt-2">Wealth, Fame, Power</motion.p></motion.div><div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">{portfolioData.projects.map((project, index) => (<motion.a key={project.name} href={project.github} target="_blank" rel="noopener noreferrer" className="relative p-5 rounded-2xl border-2 overflow-hidden group block" style={{ background: 'linear-gradient(135deg, rgba(26,20,0,0.95) 0%, rgba(15,10,0,0.98) 100%)', borderColor: hoveredProject === project.name ? '#ffd700' : 'rgba(139,69,19,0.5)' }} initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: index * 0.1 }} onHoverStart={() => setHoveredProject(project.name)} onHoverEnd={() => setHoveredProject(null)} whileHover={{ y: -8, scale: 1.02, boxShadow: '0 20px 40px rgba(0,0,0,0.5), 0 0 30px rgba(255,215,0,0.3)' }}><motion.div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity" style={{ background: 'radial-gradient(ellipse at 50% 0%, rgba(255,215,0,0.2), transparent 60%)' }} /><div className="flex items-start justify-between mb-3 relative z-10"><motion.div className="text-3xl" animate={hoveredProject === project.name ? { rotate: [0, -10, 10, 0], scale: [1, 1.2, 1] } : {}} transition={{ duration: 0.5 }}>{project.icon}</motion.div><div className="text-right"><span className="text-xs px-2 py-1 rounded-full text-black font-bold" style={{ background: project.type === 'Yonko Level' ? 'linear-gradient(90deg, #ff4444, #ffd700)' : 'linear-gradient(90deg, #4a9eff, #87ceeb)' }}>{project.type}</span><p className="text-xs text-yellow-500 mt-1 font-bold">💰 {project.bounty} Berry</p></div></div><h3 className="text-lg font-bold text-white mb-2 relative z-10">{project.name}</h3><p className="text-gray-400 text-sm mb-4 line-clamp-2 relative z-10">{project.description}</p><div className="flex flex-wrap gap-1.5 relative z-10">{project.tech.map((tech, i) => (<motion.span key={tech} className="px-2 py-0.5 text-xs rounded-full" style={{ background: 'rgba(139,69,19,0.4)', color: '#d4a056', border: '1px solid rgba(212,160,86,0.4)' }} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: 0.3 + i * 0.05 }} whileHover={{ background: 'rgba(255,215,0,0.3)', borderColor: '#ffd700', color: '#ffd700', scale: 1.1 }}>{tech}</motion.span>))}</div><motion.div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1"><span className="text-yellow-600 text-xs">Claim Treasure</span><motion.span animate={{ x: [0, 5, 0] }} transition={{ duration: 1, repeat: Infinity }}>→</motion.span></motion.div></motion.a>))}</div></div></ScrollableSection>)
}

function EducationContent({ onAtTop, onAtBottom }: { onAtTop: () => void; onAtBottom: () => void }) {
  return (<ScrollableSection color="#4a9eff" onAtTop={onAtTop} onAtBottom={onAtBottom}><div className="max-w-4xl mx-auto px-6 py-8"><motion.div className="text-center mb-10" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}><motion.span className="text-5xl block mb-3" animate={{ rotate: [0, 360] }} transition={{ duration: 8, repeat: Infinity, ease: 'linear' }}>🧭</motion.span><motion.h2 className="text-4xl sm:text-5xl md:text-6xl font-bold" style={{ color: '#87ceeb', textShadow: '0 0 30px rgba(135,206,235,0.5)' }}>NAVIGATION</motion.h2><motion.p className="text-blue-300/70 italic mt-2">Knowledge is the compass</motion.p></motion.div><div className="space-y-6">{portfolioData.education.map((edu, index) => (<motion.div key={edu.school} className="relative p-8 rounded-2xl border-2 overflow-hidden group" style={{ background: 'linear-gradient(135deg, rgba(0,26,51,0.9) 0%, rgba(0,13,26,0.95) 100%)', borderColor: 'rgba(74,158,255,0.4)' }} initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8, delay: index * 0.2 }} whileHover={{ borderColor: '#4a9eff', scale: 1.02 }}><motion.div className="absolute top-2 right-4"><motion.span className="text-2xl" animate={{ rotate: [0, 360] }} transition={{ duration: 4, repeat: Infinity, ease: 'linear' }}>🗺️</motion.span></motion.div><div className="flex flex-col md:flex-row md:items-center md:justify-between relative z-10"><div className="flex items-start gap-4"><motion.span className="text-4xl" animate={{ y: [0, -5, 0] }} transition={{ duration: 2, repeat: Infinity, delay: index * 0.5 }}>{edu.icon}</motion.span><div><h3 className="text-xl font-bold text-blue-300">{edu.degree}</h3><p className="text-blue-200/80">{edu.school}</p><p className="text-blue-400/50 text-sm">{edu.location}</p></div></div><div className="text-right mt-4 md:mt-0"><p className="text-blue-300/80">{edu.period}</p><motion.p className="text-3xl font-bold text-blue-400" animate={{ scale: [1, 1.05, 1] }} transition={{ duration: 2, repeat: Infinity }}>LOG: {edu.gpa}</motion.p></div></div></motion.div>))}</div></div></ScrollableSection>)
}

function ContactContent({ onAtTop, onAtBottom }: { onAtTop: () => void; onAtBottom: () => void }) {
  const [calling, setCalling] = useState(false); const handleCall = (href: string) => { setCalling(true); setTimeout(() => { setCalling(false); window.open(href, href.startsWith('mailto') ? '_self' : '_blank') }, 1500) }
  return (<ScrollableSection color="#ffffff" onAtTop={onAtTop} onAtBottom={onAtBottom}><div className="max-w-4xl mx-auto px-6 py-8 text-center"><AnimatePresence>{calling && (<motion.div className="fixed inset-0 flex items-center justify-center pointer-events-none z-50"><motion.div className="text-center" initial={{ scale: 0 }} animate={{ scale: [0, 1.2, 1] }} exit={{ scale: 0, opacity: 0 }}><motion.span className="text-8xl block" animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ duration: 0.3, repeat: 5 }}>🐌</motion.span><motion.p className="text-2xl text-white mt-4" animate={{ opacity: [0.5, 1, 0.5] }} transition={{ duration: 0.5, repeat: 3 }}>Purupurupuru...</motion.p></motion.div></motion.div>)}</AnimatePresence><motion.div className="mb-10" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}><motion.span className="text-6xl block mb-3" animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ duration: 2, repeat: Infinity }}>🐌</motion.span><motion.h2 className="text-4xl sm:text-5xl md:text-6xl font-bold" style={{ color: '#ffffff', textShadow: '0 0 20px rgba(255,255,255,0.4)' }}>DEN DEN MUSHI</motion.h2><motion.p className="text-gray-400 italic mt-2">Purupurupuru... Kacha!</motion.p></motion.div><motion.p className="text-xl text-gray-300 max-w-2xl mx-auto mb-10" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>Ready to join my crew and sail the Grand Line together? Contact me through the transponder snail!</motion.p><motion.div className="flex flex-col sm:flex-row gap-4 justify-center" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>{[{ icon: '📧', label: 'NEWS COO', href: `mailto:${portfolioData.social.email}`, color: '#ffd700' }, { icon: '💼', label: 'MARINE HQ', href: portfolioData.social.linkedin, color: '#0077b5' }, { icon: '🐙', label: 'FISHMAN ISLAND', href: portfolioData.social.github, color: '#ff69b4' }].map((btn, i) => (<motion.button key={btn.label} onClick={() => handleCall(btn.href)} className="px-8 py-4 rounded-xl border-2 text-white font-bold tracking-wider relative overflow-hidden group" style={{ background: 'linear-gradient(135deg, rgba(0,26,51,0.95) 0%, rgba(0,13,26,0.98) 100%)', borderColor: 'rgba(74,158,255,0.4)' }} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 + i * 0.1 }} whileHover={{ scale: 1.05, borderColor: btn.color, color: btn.color, boxShadow: `0 0 30px ${btn.color}40` }} whileTap={{ scale: 0.95 }}><motion.div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity" style={{ background: `radial-gradient(ellipse at 50% 100%, ${btn.color}20, transparent 70%)` }} /><span className="relative z-10">{btn.icon} {btn.label}</span></motion.button>))}</motion.div><motion.p className="text-gray-500 mt-12" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.8 }}>📍 {portfolioData.location}</motion.p><motion.div className="mt-16 pt-8 border-t border-gray-800" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 1 }}><p className="text-gray-600 text-sm">© 2025 {portfolioData.name}. All rights reserved.</p><p className="text-gray-700 text-xs mt-2 italic">The One Piece... THE ONE PIECE IS REAL! 🏴‍☠️</p></motion.div></div></ScrollableSection>)
}